using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using System.Threading;using System.Text.Json;
internal static class Probe{
// @ACTUAL_ORDERED_HELPER@

 static readonly List<object> Checks=new();static void Check(string name,bool ok){Checks.Add(new{name,passed=ok});if(!ok)throw new Exception(name);}
 static int Main(string[] args){try{
  Check("empty rows return empty and execute no callback",ManagedOrdered2(Array.Empty<int>(),i=>throw new Exception()).Length==0);
  int visits=0;var ordered=ManagedOrdered2(Enumerable.Range(0,200).ToArray(),i=>{Interlocked.Increment(ref visits);return (object)(i*i);});Check("all200 callbacks execute exactly once in input order",visits==200&&ordered.Select(x=>(int)x).SequenceEqual(Enumerable.Range(0,200).Select(i=>i*i)));
  int active=0,max=0;var both=new CountdownEvent(2);var release=new ManualResetEventSlim(false);var outer=new Thread(()=>ManagedOrdered2(new[]{0,1},i=>{var n=Interlocked.Increment(ref active);lock(Checks)max=Math.Max(max,n);both.Signal();if(!release.Wait(5000))throw new Exception("release deadline");Interlocked.Decrement(ref active);return (object)i;}));outer.Start();Check("exactly2 workers can enter concurrently",both.Wait(5000)&&max==2);release.Set();Check("both callbacks joined before parent returns",outer.Join(5000)&&active==0);
  var later=new InvalidDataException("later-index-one");var earlier=new IOException("earliest-index-zero");var second=new ManualResetEventSlim(false);Exception? observed=null;try{ManagedOrdered2(new[]{0,1},i=>{if(i==0){if(!second.Wait(5000))throw new Exception("second absent");throw earlier;}second.Set();throw later;});}catch(Exception e){observed=e;}Check("earlier input failure identity and original stack retained",ReferenceEquals(observed,earlier)&&observed!.StackTrace!.Contains("Main"));
  var firstRunning=new ManualResetEventSlim(false);var failureEntered=new ManualResetEventSlim(false);var allowFirst=new ManualResetEventSlim(false);int extra=0;Exception? failure=null;var waiter=new Thread(()=>{try{ManagedOrdered2(new[]{0,1,2,3},i=>{if(i==0){firstRunning.Set();if(!allowFirst.Wait(5000))throw new Exception("first wait");return (object)i;}if(i==1){if(!firstRunning.Wait(5000))throw new Exception("first absent");failureEntered.Set();throw later;}Interlocked.Increment(ref extra);return (object)i;});}catch(Exception e){failure=e;}});waiter.Start();Check("declared worker failure begins",failureEntered.Wait(5000));Thread.Sleep(20);Check("failure path drains already-started worker and starts no later input",!waiter.Join(0)&&extra==0);allowFirst.Set();Check("joined failure keeps exact original exception and no callback leak",waiter.Join(5000)&&ReferenceEquals(failure,later)&&extra==0);
  var dir=Path.Combine(args[0],"inputs");Directory.CreateDirectory(dir);var files=Enumerable.Range(0,12).Select(i=>Path.Combine(dir,i+".bin")).ToArray();for(int i=0;i<files.Length;i++)File.WriteAllBytes(files[i],Enumerable.Repeat((byte)i,4096+i).ToArray());int read=0;object[] ReadAll()=>ManagedOrdered2(files,f=>{Interlocked.Increment(ref read);using var stream=File.OpenRead(f);return (object)Convert.ToHexString(SHA256.HashData(stream));});var a=ReadAll();File.WriteAllBytes(files[5],new byte[]{1,2,3});var b=ReadAll();Check("all source bytes reread on every invocation with no hash cache",read==24&&!Equals(a[5],b[5])&&a.Where((x,i)=>i!=5).SequenceEqual(b.Where((x,i)=>i!=5)));
  File.Delete(files[4]);Exception? missing=null;try{ReadAll();}catch(Exception e){missing=e;}Check("missing source remains a typed hard failure",missing is FileNotFoundException);
  for(int i=0;i<20;i++){var x=ManagedOrdered2(new[]{0,1,2},v=>(object)v);Check("repeated invocation leaves no pending work "+i,x.SequenceEqual(new object[]{0,1,2}));}
  File.WriteAllText(Path.Combine(args[0],"result.json"),JsonSerializer.Serialize(new{status="PASS",checks=Checks.Count,cases=Checks,maximumWorkers=max,fullHashReads=read,physicalIo=false,productExecuted=false},new JsonSerializerOptions{WriteIndented=true}));return 0;
 }catch(Exception e){File.WriteAllText(Path.Combine(args[0],"failure.json"),JsonSerializer.Serialize(new{status="FAIL",error=e.ToString(),checks=Checks}));return 1;}}

}
